struct Requests final:a::Requests {a::RecoverySession* recovery{};rpc::CookieCredentials credentials;rpc::Transport transport{credentials};AddressService addresses{[this](const auto& id,const std::vector<std::string>& known,std::stop_token stop){return FetchAddresses(transport,id,stop,{},known);}};RefreshService refresh{[this](const auto& r,std::stop_token stop){return FetchRefresh(transport,r,stop);}};ConnectionService connection{[this](const auto& c,std::stop_token stop){return ProbeCapabilities(transport,c,stop);},[this](bool b){refresh.SetOffline(b,RefreshMonotonicMs());addresses.SetOffline(b);}};ConnectionService* Connection() override{return &connection;}RefreshService* Refresh() override{return &refresh;}AddressService* Addresses() override{return &addresses;}a::RecoverySession* Recovery() override{return recovery;}a::HostObservations Observe() const override{return a::ConnectionObservations(connection,refresh);}a::Availability CanSubmit(const a::Request&) const override{return {false,"No mutation port"};}a::Receipt Submit(const a::Request&) override{throw std::runtime_error("unexpected host mutation");}};
struct Observer final:platform::NativeObserver {
    Requests requests;sh::State state;sh::Facts facts;std::filesystem::path out;Display* display{};void* xtst{};int(*motion)(Display*,int,int,int,unsigned long){};int(*button)(Display*,unsigned int,Bool,unsigned long){};int(*key)(Display*,unsigned int,Bool,unsigned long){};int checks{},stage{},base{};int64_t expected{};bool done{},cleaned{};std::string selected,address;float before_split{};std::chrono::steady_clock::time_point started=std::chrono::steady_clock::now();
    void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
    bool CaptureFramebuffer() const override{return true;}
    void Idle(platform::NativeHost&,const platform::NativeFrame&) override{if(std::chrono::steady_clock::now()-started>std::chrono::seconds(25))throw std::runtime_error("native address deadline");}
    void Click(platform::NativeHost& host,const ui::components::ItemFacts& item,bool down){const auto& r=item.rect;Check(item.visible && !item.disabled && r[0]>=0 && r[1]>=0 && r[2]<=960 && r[3]<=640,"native address action reachable");int x{},y{};glfwGetWindowPos(host.Window(),&x,&y);Check(motion(display,-1,x+int((r[0]+r[2])/2),y+int((r[1]+r[3])/2),0),"native address pointer");Check(button(display,1,down,0),"native address click");XSync(display,False);}
    void Capture(const platform::NativeFrame& f,const char* name){std::ofstream file(out/(std::string(name)+".ppm"),std::ios::binary);file<<"P6\n"<<f.framebuffer_width<<' '<<f.framebuffer_height<<"\n255\n";for(int y=f.framebuffer_height-1;y>=0;--y)for(int x=0;x<f.framebuffer_width;++x)file.write(reinterpret_cast<const char*>(f.rgba.data()+(size_t(y)*f.framebuffer_width+x)*4),3);Check(bool(file),"address framebuffer retained");Check(state.presentation.Tree().Validate() && !state.presentation.Tree().overflow,"address semantics valid and bounded");std::ofstream(out/(std::string(name)+".semantics.txt"))<<state.presentation.Snapshot();}
    void Frame(platform::NativeHost& host,const platform::NativeFrame& f) override {
        auto* doc=state.documents.Find(1);if(!doc)return;
        if(stage==0){if(f.rendered_frames<4)return;Click(host,facts.navigation[3],true);base=int(f.rendered_frames);stage=1;return;}
        if(stage==1 && int(f.rendered_frames)>base){Click(host,facts.navigation[3],false);stage=2;return;}
        const auto history=a::HistoryForDocument(*doc,requests.refresh,{});const auto view=history && history->identity?requests.addresses.View(*history->identity):AddressView{};
        if(stage==2){if(!view.snapshot || !view.current || !history->chain_current || !history->ledger->Complete() || facts.address_counts[0]==0)return;Check(f.width==960 && f.height==640 && f.effective_scale==1.5F && !f.gl_error && f.font_texture,"actual native addresses960x640/150 percent");Check(facts.address_counts[0]>0 && facts.address_counts[1]>0,"both actual receive/change sequences visible");Check(facts.address_tables[0].y+facts.address_tables[0].h<=facts.address_tables[1].y && facts.address_tables[1].y+facts.address_tables[1].h<=facts.layout.content.y+facts.layout.content.h,"stacked native panes remain bounded");Check(std::any_of(view.snapshot->rows.begin(),view.snapshot->rows.end(),[](const auto& row){return row.lookahead && !row.internal;}) && std::any_of(view.snapshot->rows.begin(),view.snapshot->rows.end(),[](const auto& row){return row.lookahead && row.internal;}),"real unused-index look-ahead on both branches");const auto rows=ReconcileAddresses(*view.snapshot,history->ledger,true);Money total=Money::Satoshis(0);for(const auto& row:rows){Check(bool(row.value),"current address value is known for fully covered actual fixture");const auto sum=total.Add(*row.value);Check(bool(sum),"checked address balance sum");total=*sum;}Check(total.sats()==expected,"actual address balances reconcile exactly to authoritative wallet RPC");const auto funded=std::find_if(rows.begin(),rows.end(),[](const auto& row){return !row.derived.internal && !row.outputs.empty();});Check(funded!=rows.end(),"actual public script associates real wallet output");selected=funded->derived.key;address=funded->derived.address;doc->addresses.selected=selected;state.addresses.at(1).reveal_selected=true;stage=3;base=int(f.rendered_frames);return;}
        if(stage==3){if(int(f.rendered_frames)<base+4 || !facts.address.contains("expand-"+selected) || !facts.address.at("expand-"+selected).visible)return;Capture(f,"addresses-receive-change");Click(host,facts.address.at("expand-"+selected),true);base=int(f.rendered_frames);stage=4;return;}
        if(stage==4 && int(f.rendered_frames)>base){Click(host,facts.address.at("expand-"+selected),false);stage=5;base=int(f.rendered_frames);return;}
        if(stage==5 && int(f.rendered_frames)>base+4){Check(doc->addresses.expanded.contains(selected),"native output expansion uses exact public address key");Capture(f,"address-outpoints");Click(host,facts.address.at("copy"),true);stage=6;base=int(f.rendered_frames);return;}
        if(stage==6 && int(f.rendered_frames)>base){Click(host,facts.address.at("copy"),false);stage=7;base=int(f.rendered_frames);return;}
        if(stage==7 && int(f.rendered_frames)>base+3){Check(host.InputState().clipboard_writes==1,"native address copy routed once to existing clipboard boundary");before_split=doc->addresses.split;Click(host,facts.address.at("splitter"),true);stage=8;base=int(f.rendered_frames);return;}
        if(stage==8 && int(f.rendered_frames)>base){int x{},y{};glfwGetWindowPos(host.Window(),&x,&y);const auto r=facts.address.at("splitter").rect;Check(motion(display,-1,x+int((r[0]+r[2])/2),y+int((r[1]+r[3])/2)+24,0),"native splitter drag");XSync(display,False);stage=9;base=int(f.rendered_frames);return;}
        if(stage==9 && int(f.rendered_frames)>base){Check(button(display,1,False,0),"native splitter release");XSync(display,False);stage=10;base=int(f.rendered_frames);return;}
        if(stage==10 && int(f.rendered_frames)>base+3){Check(doc->addresses.split>before_split && doc->addresses.split<=.8F,"native resizable address panes");bool range=false;for(const auto& node:state.presentation.Tree().nodes)if(node.id==facts.address.at("splitter").id)range=std::abs(node.numericValue-doc->addresses.split*100)<.01 && node.minimumValue<=node.numericValue && node.maximumValue>=node.numericValue && !node.state.readOnly;Check(range,"native splitter numeric accessibility matches actual pane ratio");Capture(f,"addresses-resized");Click(host,facts.address.at("transactions"),true);stage=11;base=int(f.rendered_frames);return;}
        if(stage==11 && int(f.rendered_frames)>base){Click(host,facts.address.at("transactions"),false);stage=12;base=int(f.rendered_frames);return;}
        if(stage==12 && int(f.rendered_frames)>base+3){Check(doc->addresses.transactions && doc->addresses.selected==selected,"native header option preserves public selection");Key(XK_Control_L,true);Key(XK_Shift_L,true);Key(XK_h,true);stage=13;base=int(f.rendered_frames);return;}
        if(stage==13 && int(f.rendered_frames)>base){Key(XK_h,false);Key(XK_Shift_L,false);Key(XK_Control_L,false);stage=14;base=int(f.rendered_frames);return;}
        if(stage==14 && int(f.rendered_frames)>base+3){Check(state.privacy.hidden && facts.address.at("hide-empty").disabled,"native amount privacy fences financial filter");Check(state.presentation.Snapshot().find("Wallet-known address balance | Hidden")!=std::string::npos,"native address exact money concealed semantically");Capture(f,"addresses-hidden");requests.addresses.Unbind();requests.refresh.Unbind();stage=15;return;}
        if(stage==15 && !requests.addresses.Busy() && !requests.refresh.Busy()){Check(state.documents.Find(1)->addresses.selected==selected,"view identity retained after worker settlement");done=true;host.RequestClose();}
    }
    void Key(KeySym sym,bool down){Check(key(display,XKeysymToKeycode(display,sym),down,0),"native address key");XSync(display,False);}
    void Teardown(const platform::NativeTeardown& t) override{cleaned=t.renderer_cleared && t.platform_cleared && t.textures_released && t.imgui_cleared && t.context_cleared;Check(cleaned,"native address resources settled");}
};
