int main(int argc,char** argv){if(argc!=10)return 2;Observer o;o.out=argv[1];std::filesystem::create_directories(o.out);int result=1;try{const char* display=getenv("DISPLAY"),*owned=getenv("ROOTS_GUI_OWNED_TEST_DISPLAY");if(!display || !owned || std::string(display)!=owned)throw std::runtime_error("owned display required");a::RecoverySession recovery(argv[3]);o.expected=std::stoll(argv[9]);o.requests.recovery=&recovery;recovery.Start();ServerCandidate profile;profile.connection.port=uint16_t(std::stoi(argv[4]));profile.connection.credential.reference=argv[5];profile.expected_genesis=argv[6];profile.wallet=argv[7];auto& c=o.requests.connection;o.Check(c.SetDraft(profile) && c.Test(),"actual descriptor wallet Test");const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(10);while(c.Busy() && std::chrono::steady_clock::now()<end){c.Poll();std::this_thread::yield();}o.Check(c.Apply(),"actual descriptor wallet Apply");o.display=XOpenDisplay(nullptr);o.xtst=dlopen("libXtst.so.6",RTLD_NOW);if(!o.display || !o.xtst)throw std::runtime_error("XTest unavailable");o.motion=reinterpret_cast<decltype(o.motion)>(dlsym(o.xtst,"XTestFakeMotionEvent"));o.button=reinterpret_cast<decltype(o.button)>(dlsym(o.xtst,"XTestFakeButtonEvent"));o.key=reinterpret_cast<decltype(o.key)>(dlsym(o.xtst,"XTestFakeKeyEvent"));if(!o.motion || !o.button || !o.key)throw std::runtime_error("native input symbols unavailable");platform::NativeHost* current{};{platform::NativeOptions options{960,640,false,1.5F,argv[2]};options.fixed_delta_seconds=1.F/60;platform::NativeHost host(options,&o,[&](const imkit::Theme& theme,const ui::BootstrapAppearance& appearance){o.facts=platform::DrawShellFrame(*current,o.state,o.requests,theme,appearance);});current=&host;host.Run();}o.Check(o.done && o.cleaned,"native address journey complete");result=0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';}if(o.display)XCloseDisplay(o.display);if(o.xtst)dlclose(o.xtst);std::ofstream(o.out/"result.json")<<"{\"selected\":1,\"executed\":1,\"passed\":"<<!result<<",\"failed\":"<<result<<",\"skipped\":0,\"checks\":"<<o.checks<<",\"teardown\":"<<o.cleaned<<"}\n";return result;}
